const heading=page.querySelector('.page-heading');const root=document.createElement('section');root.id='adaz-curriculum';if(heading)heading.insertAdjacentElement('afterend',root);else page.prepend(root);

let current='icfes',activeModule=null,activeQuestion=null,activeAnswer=null;
function save(){progress.done=[...done];try{localStorage.setItem(KEY,JSON.stringify(progress))}catch{}}
function kindFor(id){return id==='icfes'?'icfes':id==='ielts'?'ielts':id==='medicine'?'medicine':'business'}
function filterFor(track,module){
 if(track==='icfes')return ({'Sociales y Ciudadanas':'Sociales','Ciencias Naturales':'Ciencias'})[module[0]]||module[0];
 if(track==='ielts')return ['Listening','Reading'].includes(module[0])?module[0]:null;
 return track==='medicine'?'Ciencias':'Negocio';
}
function promptFor(track,module,index){
 if(track==='ielts'&&module[0]==='Writing')return module[1].includes('Task 1')?'Task 1: The table shows the share of students travelling to college by bus (48% to 35%), walking (22% to 30%), cycling (10% to 25%) and car (20% to 10%) between 2015 and 2025. Summarise the main features in at least 150 words.':'Task 2: Some people believe schools should teach practical financial and digital skills alongside academic subjects. To what extent do you agree? Write at least 250 words.';
 if(track==='ielts'&&module[0]==='Speaking')return module[1].includes('Part 1')?'Part 1: How do you organise your study time? What helps you concentrate? Give a direct answer and one relevant detail.':module[1].includes('Part 2')?'Part 2: Describe a skill you learned that has been useful in daily life. Explain how you learned it and why it matters.':'Part 3: How should schools prepare students for changes in the workplace? Compare at least two perspectives and justify your view.';
 if(track==='medicine')return 'Caso académico: explica cómo se relaciona el tema “'+module[1]+'” con la estructura y función de un sistema biológico. No uses este ejercicio para autodiagnóstico.';
 if(track==='oro')return 'Caso de negocio: aplica “'+module[1]+'” a una decisión realista de Oro Lámina. Indica qué dato necesitas, qué compararías y qué decisión tomarías sin inventar información del proveedor.';
 return 'Reto Saber 11: resuelve una pregunta relacionada con “'+module[1]+'”. Identifica la competencia evaluada, la evidencia disponible y por qué descartas los distractores.';
}
function methodText(id){
 if(id==='icfes')return 'Referencia metodológica: Grupo500 describe públicamente un ciclo con clases por áreas, grabaciones 24/7, guías descargables, simulacros tipo ICFES con retroalimentación y acompañamiento. ADAZ adapta esa secuencia a clases propias, práctica y análisis de errores; no incluye ni suplanta las clases en vivo, grabaciones, tutorías o materiales privados de Grupo500.';
 if(id==='ielts')return 'Ruta de cuatro habilidades con tareas originales. Cambridge aporta preparación y muestras oficiales; Richmond Practice Tests for IELTS ofrece cuatro pruebas Academic completas y material interactivo adicional en su plataforma, cuyo acceso puede depender del producto adquirido. Oxford complementa vocabulario, gramática y aprendizaje autónomo; sus recursos no se presentan como un curso oficial de IELTS.';
 if(id==='medicine')return 'Ruta introductoria basada en textos abiertos de biología y anatomía-fisiología. Las clases son educativas, no sustituyen formación universitaria ni permiten diagnosticar o tratar enfermedades.';
 return 'Ruta aplicada a producto, compras, inventario, costos, flujo de caja, ventas y marketing. Los ejemplos son simulados; los datos reales se registran únicamente en el módulo privado de Business.';
}
function openModule(i){
 const t=tracks.find(x=>x.id===current);activeModule=i;activeAnswer=null;
 const m=t.modules[i],filter=filterFor(current,m);
 activeQuestion=(current==='ielts'&&['Writing','Speaking'].includes(m[0]))?null:(window.ADAZExamBank?.next?.(kindFor(current),filter)||null);
 render();
}
function lessonBody(track,m,index){
 let explain='',example='',pitfall='';
 if(track==='icfes'){
  if(m[0]==='Matemáticas'&&m[1].includes('numérico')){explain='Una razón compara dos cantidades; una proporción afirma que dos razones son equivalentes. Para trabajar porcentajes, convierte p% en p/100 y multiplica por la cantidad base. En cambios sucesivos, aplica cada factor al valor actualizado.';example='El 15% de 80.000 es 80.000 × 0,15 = 12.000. Con un descuento, el precio final es 80.000 − 12.000 = 68.000.';pitfall='No confundas el valor del descuento con el precio final. Comprueba siempre cuál es la cantidad base.'}
  else if(m[0]==='Matemáticas'&&m[1].includes('Funciones')){explain='Una función relaciona cada entrada con una salida. En una recta y = mx + b, m representa la variación por unidad y b el valor inicial. La tabla, la gráfica y la expresión algebraica describen el mismo modelo desde formas distintas.';example='Si un servicio cobra 4.000 de base y 1.800 por kilómetro, C(x)=1.800x+4.000. Para 5 km: C(5)=13.000.';pitfall='No intercambies la pendiente con el intercepto. Verifica qué variable depende de cuál y conserva las unidades.'}
  else if(m[0]==='Matemáticas'&&m[1].includes('Geometría')){explain='El perímetro mide el contorno y se expresa en unidades lineales; el área mide superficie y usa unidades cuadradas; el volumen mide espacio y usa unidades cúbicas. En semejanza, las longitudes cambian por un factor k y las áreas por k².';example='Un rectángulo de 8 m por 5 m tiene perímetro 2(8+5)=26 m y área 8×5=40 m².';pitfall='No confundas perímetro con área. Dibuja la figura, anota unidades y revisa qué magnitud pide el problema.'}
  else if(m[0]==='Matemáticas'&&m[1].includes('Estadística')){explain='La media usa todos los valores y es sensible a extremos; la mediana es el valor central ordenado; la moda es el más frecuente. La probabilidad compara casos favorables con casos posibles cuando los resultados son equiprobables.';example='En 12, 15, 15, 18 y 20, la mediana es 15. Si hay 2 fichas azules entre 10, P(azul)=2/10=1/5.';pitfall='Una asociación estadística no demuestra causalidad. Revisa tamaño y selección de la muestra antes de generalizar.'}
  else if(m[0]==='Lectura Crítica'&&m[1].includes('Estructura')){explain='Un argumento combina una tesis (lo que se defiende), razones y evidencias. Los conectores indican relaciones: “sin embargo” introduce contraste; “por tanto” señala consecuencia; una concesión reconoce un límite sin abandonar necesariamente la tesis.';example='Si un autor afirma que el transporte público debe priorizarse porque amplía el acceso y reduce ocupación vial, la primera idea es la tesis y las dos siguientes son razones.';pitfall='No confundas el tema general con la tesis. Resume qué quiere que aceptes el autor y localiza las razones que la respaldan.'}
  else if(m[0]==='Lectura Crítica'&&m[1].includes('Perspectiva')){explain='Evaluar fuentes exige identificar autor, fecha, propósito, audiencia, evidencia y contexto. Una fuente primaria registra directamente un hecho o documento; una secundaria lo interpreta. La confiabilidad depende de la pregunta y de la corroboración.';example='Para estudiar una política, contrasta el texto oficial con estadísticas públicas y evaluaciones independientes; explica qué aporta y qué no puede demostrar cada fuente.';pitfall='No aceptes una afirmación solo por su popularidad, título o tono seguro. Contrasta autoría y evidencia.'}
  else if(m[0]==='Lectura Crítica'){explain='La comprensión literal recupera información explícita; la inferencial conecta pistas para derivar una conclusión; la crítica evalúa intención, argumentos y límites. Toda inferencia válida debe poder señalarse con evidencia textual.';example='Si el texto dice que aumentaron las visitas, pero no midió aprendizaje, puedes concluir que hubo más visitas; no que los resultados académicos mejoraron.';pitfall='No agregues conocimientos externos cuando la pregunta exige responder únicamente con lo que el texto permite concluir.'}
  else if(m[0]==='Sociales y Ciudadanas'&&m[1].includes('Estado')){explain='El Estado social de derecho combina instituciones, normas y garantías de derechos. La separación de poderes distribuye funciones y crea controles. La participación ciudadana incluye mecanismos institucionales y deliberación informada.';example='Ante una decisión pública que limita un derecho, analiza fundamento legal, finalidad, necesidad y proporcionalidad; identifica también las vías institucionales para controvertirla.';pitfall='No supongas que una autoridad tiene poder ilimitado. Examina competencias, derechos en tensión y mecanismos de control.'}
  else if(m[0]==='Sociales y Ciudadanas'&&m[1].includes('Historia')){explain='El análisis histórico ubica fuentes en tiempo y contexto, distingue causas de consecuencias y reconoce continuidades y rupturas. Los procesos sociales suelen tener causas múltiples y actores con intereses distintos.';example='Al comparar dos relatos sobre un mismo acontecimiento, revisa cuándo se produjeron, quién los escribió, qué evidencia citan y qué voces omiten.';pitfall='No expliques un proceso complejo con una sola causa ni juzgues una fuente sin considerar su contexto.'}
  else if(m[0]==='Sociales y Ciudadanas'){explain='Los fenómenos económicos, territoriales y ambientales conectan decisiones individuales, instituciones y condiciones geográficas. Oferta, demanda, inflación, empleo y desigualdad son conceptos que deben leerse junto con datos y población afectada.';example='Si la demanda aumenta y la oferta permanece constante, el precio puede subir, siempre que otros factores relevantes no cambien.';pitfall='No conviertas una tendencia posible en una regla absoluta. Declara los supuestos y revisa a quién beneficia o afecta una decisión.'}
  else if(m[0]==='Ciencias Naturales'&&m[1].includes('Biología')){explain='En biología, estructura y función se explican juntas: la membrana regula intercambios, las mitocondrias participan en la producción de ATP y el ADN almacena información hereditaria. Los sistemas vivos interactúan con su ambiente.';example='Si una célula necesita energía utilizable, analiza cómo los nutrientes participan en rutas metabólicas que permiten producir ATP; no atribuyas toda la función a un solo organelo.';pitfall='Evita memorizar nombres aislados. Relaciona estructura, función, proceso y evidencia del modelo.'}
  else if(m[0]==='Ciencias Naturales'&&m[1].includes('Química')){explain='La materia se transforma conservando átomos. Los enlaces explican propiedades; las soluciones describen mezclas homogéneas. El pH es logarítmico: una diferencia de una unidad representa un factor de diez en concentración de H⁺ en el modelo habitual.';example='Entre pH 3 y pH 5 hay dos unidades de diferencia: la solución de pH 3 tiene 100 veces más H⁺ que la de pH 5, bajo el modelo simplificado.';pitfall='No trates la escala de pH como lineal ni olvides balancear la materia en una reacción.'}
  else if(m[0]==='Ciencias Naturales'&&m[1].includes('Física')){explain='La física modela cambios mediante magnitudes, unidades y relaciones. Rapidez media = distancia/tiempo; la fuerza neta explica cambios de movimiento; la energía se transfiere y transforma.';example='Un ciclista recorre 150 m en 30 s: rapidez media = 150/30 = 5 m/s.';pitfall='Comprueba unidades, dirección y condiciones del modelo. No confundas rapidez con velocidad vectorial.'}
  else if(m[0]==='Ciencias Naturales'){explain='Una investigación parte de una pregunta, propone una explicación y diseña una comparación. La variable independiente se modifica; la dependiente se mide; las variables controladas se mantienen comparables.';example='Si se estudia el efecto de la luz en plantas, cambia la cantidad de luz y mide el crecimiento, manteniendo iguales agua, especie y duración.';pitfall='Si cambias luz y agua al mismo tiempo, no podrás atribuir con claridad el resultado a uno de los factores.'}
  else{explain='En inglés, interpreta vocabulario y gramática dentro de un contexto. Los conectores muestran relaciones, los pronombres remiten a referentes y el propósito comunicativo ayuda a entender avisos, diálogos y textos.';example='“The first design was cheaper; however, the second was more durable.” However señala contraste entre dos ventajas distintas.';pitfall='No traduzcas palabra por palabra ni elijas una opción solo porque repite una palabra del texto.'}
 }else if(track==='ielts'){
  if(m[0]==='Listening'){explain='Antes de escuchar, lee la instrucción y predice si necesitas un nombre, fecha, cifra o lugar. Durante el audio, identifica paráfrasis, cambios de decisión y distractores. Respeta el límite de palabras y revisa ortografía y plural.';example='Si alguien dice “I planned Monday, but Wednesday instead”, la respuesta final es Wednesday. La primera fecha funciona como distractor.';pitfall='No respondas con el primer dato oído. Sigue la corrección final y comprueba que la respuesta encaje gramaticalmente.'}
  else if(m[0]==='Reading'){explain='Usa lectura rápida para reconocer estructura y lectura de búsqueda para localizar evidencia. Las preguntas suelen parafrasear el texto. True/Yes exige confirmación; False/No exige contradicción; Not Given significa que el texto no permite decidir.';example='Si el pasaje informa que aumentó el número de visitantes pero no habla de satisfacción, la afirmación “visitors were more satisfied” es Not Given.';pitfall='No uses conocimientos del mundo para completar información ausente. La respuesta debe depender del pasaje.'}
  else if(m[0]==='Writing'&&m[1].includes('Task 1')){explain='Task 1 Academic exige resumir información visual con precisión. Introduce qué muestra el gráfico, selecciona rasgos principales y escribe una overview clara. Agrupa datos relevantes y compara; no expliques causas que el gráfico no ofrece.';example='“Overall, cycling increased substantially, while car use declined.” Esa overview sintetiza dos tendencias sin inventar motivos.';pitfall='No enumeres cada cifra ni omitas la visión general. Usa comparaciones correctas y unidades.'}
  else if(m[0]==='Writing'&&m[1].includes('Task 2')){explain='Task 2 evalúa respuesta a la consigna, coherencia y cohesión, vocabulario y precisión/variedad gramatical. Define una postura, desarrolla cada párrafo con razón y ejemplo y responde todas las partes de la pregunta.';example='Tesis: “Schools should teach financial literacy because it helps students compare borrowing costs and plan realistic budgets.” Luego desarrolla una razón con un ejemplo concreto.';pitfall='No uses vocabulario sofisticado si reduce precisión. Una introducción general no sustituye una postura clara.'}
  else if(m[0]==='Writing'){explain='Los cuatro criterios de Writing son Task Achievement/Response, Coherence and Cohesion, Lexical Resource y Grammatical Range and Accuracy. Cada uno evalúa una dimensión distinta del desempeño.';example='Revisa un texto en cuatro pasadas: ¿respondí la consigna?, ¿el orden es lógico?, ¿las palabras son precisas?, ¿las estructuras son correctas y variadas?';pitfall='No confundas una banda orientativa de ADAZ con una calificación certificada. Usa los descriptores oficiales o feedback cualificado.'}
  else if(m[1].includes('Part 1')){explain='Speaking Part 1 trata temas familiares. Responde de forma directa y amplía con una razón o detalle. La naturalidad, inteligibilidad y continuidad importan más que memorizar respuestas largas.';example='“I usually plan my week on Sunday because it helps me balance schoolwork and free time.” Respuesta directa más razón.';pitfall='No memorices párrafos completos ni respondas con una sola palabra cuando puedes desarrollar una idea breve.'}
  else if(m[1].includes('Part 2')){explain='Speaking Part 2 requiere una exposición individual a partir de una tarjeta. Usa el minuto de preparación para anotar palabras clave: contexto, dos detalles, resultado y reflexión. Mantén un hilo claro.';example='Para describir una habilidad, organiza: cuándo la aprendiste, cómo practicaste, qué dificultad tuviste y por qué te sirve.';pitfall='No escribas un guion completo durante la preparación. Usa notas breves para sostener la fluidez.'}
  else{explain='Speaking Part 3 amplía el tema hacia ideas abstractas y sociales. Compara perspectivas, explica causas y consecuencias, matiza y ofrece ejemplos relevantes.';example='“One advantage is access; however, this depends on reliable infrastructure and teacher support.” Presenta una idea y una condición.';pitfall='No repitas la misma idea con sinónimos. Desarrolla razones y reconoce matices.'}
 }else if(track==='medicine'){
  if(m[0]==='Biología celular'){explain='La célula es la unidad estructural y funcional básica. La membrana plasmática regula el intercambio; el citoplasma alberga procesos; el núcleo contiene la mayor parte del ADN en células eucariotas; las mitocondrias participan en la producción de ATP.';example='Cuando una célula necesita energía, los nutrientes entran en rutas metabólicas que permiten transferir energía a ATP, que después se utiliza en procesos celulares.';pitfall='No atribuyas toda la producción de energía a un solo paso ni confundas ADN con proteína.'}
  else if(m[0]==='Genética y biología molecular'){explain='El ADN almacena información hereditaria. En la expresión génica, la información puede transcribirse a ARN y traducirse en una secuencia de aminoácidos. Genotipo describe variantes genéticas; fenotipo incluye rasgos observables influenciados también por ambiente.';example='Una mutación puede cambiar un codón; por la redundancia del código genético, algunos cambios no alteran el aminoácido codificado.';pitfall='No supongas que un solo gen determina por completo un rasgo complejo.'}
  else if(m[0]==='Anatomía y fisiología'){explain='La anatomía estudia estructuras y relaciones; la fisiología estudia funciones. La homeostasis mantiene variables internas dentro de rangos compatibles mediante receptores, centros integradores y efectores, a menudo con retroalimentación negativa.';example='Si aumenta la temperatura corporal, la sudoración ayuda a reducirla: la respuesta contrarresta el cambio inicial.';pitfall='No estudies órganos como piezas aisladas. Relaciona sistemas, regulación y función.'}
  else if(m[0]==='Microbiología e inmunología'){explain='El organismo cuenta con barreras físicas y químicas, inmunidad innata de respuesta inicial e inmunidad adaptativa más específica. Los linfocitos B pueden diferenciarse en células plasmáticas que producen anticuerpos.';example='La vacunación expone al sistema inmune a un antígeno de forma controlada para favorecer memoria inmunológica; no es una garantía absoluta de que nunca habrá infección.';pitfall='No confundas prevención con tratamiento ni generalices la respuesta inmune a todos los microorganismos.'}
  else if(m[0]==='Epidemiología y salud pública'){explain='La epidemiología estudia patrones de salud en poblaciones. Incidencia cuenta casos nuevos en un periodo; prevalencia cuenta casos existentes en un momento o periodo. Los determinantes sociales influyen en exposición y acceso a recursos.';example='Una campaña puede reducir casos nuevos (incidencia) sin que la prevalencia caiga de inmediato, porque los casos existentes permanecen durante un tiempo.';pitfall='No interpretes una tasa sin conocer población, periodo, definición del caso y método de medición.'}
  else{explain='La investigación formula una pregunta, define población y variables, elige un diseño y evalúa sesgos. La ética exige respeto, consentimiento informado, confidencialidad y comunicación honesta.';example='Una pregunta PICO identifica población, intervención o exposición, comparación y resultado para enfocar una búsqueda de evidencia.';pitfall='Correlación no demuestra causalidad. Un estudio observacional puede estar afectado por variables de confusión.'}
 }else{
  if(m[0]==='Producto y proveedor'&&m[1].includes('Especificaciones')){explain='En joyería comercial, diferencia el material declarado y el proceso: oro laminado, baño y otros recubrimientos no son equivalentes. La descripción debe basarse en ficha técnica, factura y confirmación del proveedor.';example='Si la ficha confirma tipo de recubrimiento y condiciones de cuidado, comunica exactamente esos datos y deja por escrito los límites de garantía.';pitfall='No prometas oro macizo, quilataje, número de capas o duración si no están documentados.'}
  else if(m[0]==='Producto y proveedor'){explain='Evalúa proveedores por costo total puesto en tu inventario, mínimos, plazo, trazabilidad, consistencia de lotes, envío, devoluciones y soporte. Conserva evidencia de cada acuerdo.';example='Compara dos cotizaciones incluyendo precio, transporte, tiempo y política de reposición; la opción más barata no siempre tiene menor costo total.';pitfall='No decidas solo por precio unitario ni confundas una promesa verbal con una condición escrita.'}
  else if(m[0]==='Operaciones'){explain='Un SKU identifica una referencia y variante. Separa existencias físicas, reservas, pedidos por encargo y unidades en tránsito. Cada entrada y salida debe quedar registrada para conciliar el saldo.';example='Si tienes 8 unidades físicas y 3 están reservadas, quedan 5 disponibles para ofrecer de inmediato; las unidades en camino aún no son inventario disponible.';pitfall='No vendas dos veces una pieza reservada ni cuentes como disponible un pedido que no has recibido.'}
  else if(m[0]==='Finanzas'&&m[1].includes('Costo')){explain='El costo atribuible incluye compra y gastos directos como envío, empaque y comisión. Ganancia bruta = precio cobrado − costo atribuible. Margen bruto = ganancia bruta / precio cobrado × 100.';example='Si una pieza cuesta 36.000 y se vende en 60.000, la ganancia bruta es 24.000 y el margen es 40% antes de costos fijos.';pitfall='No confundas margen con recargo (markup) ni llames utilidad neta a una cifra que no resta costos fijos y otros gastos.'}
  else if(m[0]==='Finanzas'){explain='Flujo de caja registra dinero que entra y sale efectivamente. Una venta a crédito puede generar una cuenta por cobrar, pero no aumenta el efectivo disponible hasta que se recibe el pago.';example='En un pedido de 65.000 con anticipo recibido de 20.000, la caja aumenta 20.000 y quedan 45.000 pendientes.';pitfall='No confundas ventas, utilidad y efectivo. Separa capital comprometido, saldos pendientes y dinero libre.'}
  else if(m[0]==='Ventas y servicio'){explain='Un proceso comercial claro registra consulta, cotización, confirmación, pago, preparación, entrega y posventa. Comunica precio, material documentado, tiempos, cuidado y condiciones antes de aceptar el pedido.';example='Envía un resumen escrito con referencia, valor, anticipo, saldo, fecha estimada y condiciones acordadas; confirma la entrega.';pitfall='No marques una reserva como venta cobrada ni prometas fechas que dependen de un proveedor sin confirmar.'}
  else if(m[0]==='Marketing'){explain='La propuesta de valor explica para quién es la marca, qué necesidad atiende y qué la diferencia. El contenido debe responder preguntas reales y medir resultados como consultas, conversión y recompra.';example='Una publicación de cuidado del producto puede incluir detalle real, instrucciones verificadas y una invitación clara a consultar disponibilidad.';pitfall='No inventes reseñas, escasez, garantías ni características del material para aumentar conversiones.'}
  else{explain='La garantía y la información al consumidor deben ser claras, verificables y coherentes con las obligaciones legales. Las condiciones comerciales adicionales no eliminan derechos mínimos del consumidor.';example='Entrega por escrito cobertura, duración, exclusiones válidas, canal de atención y evidencia de compra; revisa reglas vigentes antes de ofrecer condiciones.';pitfall='No uses una garantía propia para prometer algo que el proveedor no respalda ni para limitar derechos legales.'}
 }
 const advanced=track==='icfes'?{label:'Estrategia Saber 11',steps:['Identifica la competencia que se está evaluando, no solo el tema.','Separa información explícita, inferencias y supuestos.','Descarta distractores por evidencia: contradicción, exageración, causalidad no probada o dato irrelevante.','Justifica la respuesta con una pista del enunciado, una operación o una relación entre variables.'],task:'Después de resolver, escribe qué evidencia hace correcta la opción y qué error de razonamiento representa cada distractor.'}:track==='ielts'?{label:'Estrategia IELTS',steps:['Lee con precisión la instrucción y el criterio de respuesta.','Identifica paráfrasis, conectores, contraste y propósito comunicativo.','Controla el tiempo sin sacrificar comprensión ni coherencia.','Revisa precisión, gramática, vocabulario y cumplimiento de la tarea.'],task:'Registra qué habilidad evalúa la actividad, qué estrategia aplicaste y qué cambiarías en un segundo intento.'}:track==='medicine'?{label:'Razonamiento biomédico',steps:['Ubica el proceso en su nivel biológico: molécula, célula, tejido, órgano o sistema.','Relaciona estructura, función y regulación.','Explica la secuencia mecanismo → cambio → consecuencia.','Distingue una explicación académica de una conclusión clínica.'],task:'Construye un esquema con componentes, función, interacción y una variable que podría modificar el proceso.'}:{label:'Decisión empresarial',steps:['Define la decisión y el periodo que estás analizando.','Usa datos verificables de compra, gastos, inventario, ventas y pagos.','Calcula costos y márgenes sin confundir ingreso, utilidad bruta y utilidad neta.','Decide qué acción tomar y qué indicador revisarás después.'],task:'Aplica el concepto a un caso de Oro Laminado. Si falta un dato real, déjalo como pendiente y no lo inventes.'};
 const drill=track==='ielts'&&m[0]==='Writing'?'Planifica una respuesta con postura central, dos ideas desarrolladas y una conclusión. Revisa los cuatro criterios de evaluación antes de finalizar.':track==='ielts'&&m[0]==='Speaking'?'Responde en voz alta, desarrolla una razón y un ejemplo, y evalúa claridad, coherencia y precisión.':track==='ielts'&&m[0]==='Listening'?'Predice el tipo de palabra que falta, escucha los cambios de opinión y comprueba ortografía y límite de palabras.':track==='ielts'&&m[0]==='Reading'?'Localiza el párrafo, encuentra la paráfrasis y clasifica cada afirmación según la evidencia textual.':track==='icfes'&&m[0]==='Lectura Crítica'?'Compara la tesis, las razones y las evidencias; identifica qué conclusión se puede inferir y cuál excede el texto.':track==='icfes'&&m[0]==='Matemáticas'?'Representa los datos, elige una operación o modelo, resuelve y verifica unidades y plausibilidad.':track==='medicine'?'Explica el proceso de forma causal y dibuja cómo interactúan sus componentes.':'Resuelve el caso con cifras y registra qué información adicional necesitarías para decidir con confianza.';
 return '<div class="lesson-body"><div><b>Conceptos clave</b><p>'+esc(explain)+'</p></div><div><b>Ejemplo trabajado</b><p>'+esc(example)+'</p></div><div><b>Error frecuente</b><p>'+esc(pitfall)+'</p></div><div><b>Temario de esta clase</b><p>'+esc(m[2])+'</p><p><b>Estrategia:</b> '+esc(m[3])+'</p></div><div class="lesson-deep"><b>'+esc(advanced.label)+'</b><ol>'+advanced.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><div class="lesson-drill"><b>Práctica de transferencia</b><p>'+esc(drill)+'</p><p>'+esc(advanced.task)+'</p></div></div></div>';
}
function questionHTML(t,m){
 if(activeQuestion){
  const x=activeQuestion;
  return '<div class="lesson-quiz"><div class="lesson-kicker">COMPRUEBA LO APRENDIDO · PREGUNTA NUEVA</div><h4>'+esc(x.text)+'</h4><div class="lesson-options">'+x.opts.map((o,i)=>'<button data-curr-answer="'+i+'" '+(activeAnswer!==null?'disabled':'')+' class="'+(activeAnswer===i?'chosen':'')+'">'+String.fromCharCode(65+i)+'. '+esc(o)+'</button>').join('')+'</div>'+(activeAnswer!==null?'<div class="lesson-feedback"><b>'+(activeAnswer===x.a?'Correcto':'Revisa el razonamiento')+'</b><p>'+esc(x.why)+'</p><button class="curr-btn" data-curr-next-question>Otra pregunta nueva →</button></div>':'<p class="lesson-hint">Elige una respuesta. La explicación aparecerá al instante y la pregunta no volverá a salir hasta recorrer el banco disponible.</p>')+'</div>';
 }
 const prompt=promptFor(current,m,activeModule);
 return '<div class="lesson-quiz"><div class="lesson-kicker">ACTIVIDAD APLICADA · RESPUESTA ABIERTA</div><h4>'+esc(prompt)+'</h4><textarea data-curr-response rows="5" placeholder="Desarrolla tu respuesta, argumentos o esquema aquí...">'+esc(progress.notes?.[current+':'+activeModule]||'')+'</textarea><div class="lesson-hint">Al guardar, conserva tu respuesta para retomarla. En IELTS Writing/Speaking puedes contrastar tu trabajo con los descriptores oficiales enlazados arriba.</div><button class="curr-btn" data-curr-save-response>Guardar mi trabajo</button><span class="lesson-saved" aria-live="polite"></span></div>';
}
function render(){
 if(!root.isConnected){const heading=page.querySelector('.page-heading');if(heading)heading.insertAdjacentElement('afterend',root);else page.append(root)}
 const t=tracks.find(x=>x.id===current)||tracks[0],all=t.modules.length,finished=t.modules.filter((m,i)=>done.has(t.id+':'+i)).length;
 const head='<div class="eyebrow">ADAZ ACADEMY · CLASES INTERACTIVAS</div><h2 style="font-size:20px;margin:6px 0">Aprende, practica y comprueba</h2><p class="curr-desc">'+esc(t.desc)+'</p><div class="track-grid">'+tracks.map(x=>'<button class="track '+(x.id===current?'active':'')+'" data-track="'+x.id+'"><b>'+esc(x.name)+'</b><small>'+esc(x.tag)+'</small></button>').join('')+'</div><div class="curr-method"><b>Cómo está construido este programa</b><p>'+esc(methodText(current))+'</p></div>';
 const progressBar='<div class="row-between" style="font-size:11px;margin-top:14px"><b>'+esc(t.name)+'</b><span>'+finished+'/'+all+' clases completadas</span></div><div class="bar"><span style="width:'+(all?finished/all*100:0)+'%"></span></div>';
 if(activeModule===null){
  root.innerHTML=head+progressBar+'<div class="curr-module-list">'+t.modules.map((m,i)=>'<article class="curr-module '+(done.has(t.id+':'+i)?'is-done':'')+'"><div><small>'+esc(m[0])+' · CLASE '+String(i+1).padStart(2,'0')+'</small><b>'+esc(m[1])+'</b><p>'+esc(m[2])+'</p></div><button class="curr-btn" data-open-module="'+i+'">'+(done.has(t.id+':'+i)?'Repasar clase':'Abrir clase')+' →</button></article>').join('')+'</div><div class="source-links"><b>Fuentes y materiales de referencia</b>'+t.source.map(s=>'<a href="'+esc(s[1])+'" target="_blank" rel="noopener noreferrer">'+esc(s[0])+' ↗</a>').join('')+'</div><div class="notice" style="margin-top:13px">Método de sesión: 5 min de recuperación activa → 20 min de clase → 15–25 min de práctica guiada → 5 min de corrección. El avance se guarda en este dispositivo.</div>';
 }else{
  const m=t.modules[activeModule],key=current+':'+activeModule;
  root.innerHTML=head+progressBar+'<button class="curr-back" data-curr-back>← Volver al temario</button><article class="curr-lesson"><div class="lesson-kicker">'+esc(m[0])+' · CLASE '+String(activeModule+1).padStart(2,'0')+'</div><h3>'+esc(m[1])+'</h3><section><h4>1. Material de estudio</h4>'+lessonBody(current,m,activeModule)+'</section><section><h4>2. Aplica lo aprendido</h4><p>Resuelve el reto sin consultar primero la respuesta. Después revisa la explicación o la pauta de evaluación.</p>'+questionHTML(t,m)+'</section><section><h4>3. Explica con tus palabras</h4><textarea data-curr-note rows="4" placeholder="Resume la idea, escribe un ejemplo o registra tus dudas...">'+esc(progress.notes?.[key]||'')+'</textarea><button class="curr-btn" data-curr-save-note>Guardar apuntes</button><span class="lesson-saved" aria-live="polite"></span></section><button class="curr-btn curr-done" data-curr-done>'+ (done.has(key)?'Clase completada ✓':'Marcar clase completada')+'</button></article><div class="source-links"><b>Consulta la fuente del tema</b>'+t.source.map(s=>'<a href="'+esc(s[1])+'" target="_blank" rel="noopener noreferrer">'+esc(s[0])+' ↗</a>').join('')+'</div>';
 }
}
root.addEventListener('click',e=>{
 const track=e.target.closest('[data-track]');if(track){current=track.dataset.track;activeModule=null;activeQuestion=null;activeAnswer=null;render();return}
 const open=e.target.closest('[data-open-module]');if(open){openModule(Number(open.dataset.openModule));return}
 if(e.target.closest('[data-curr-back]')){activeModule=null;activeQuestion=null;activeAnswer=null;render();return}
 const answer=e.target.closest('[data-curr-answer]');if(answer&&activeQuestion){activeAnswer=Number(answer.dataset.currAnswer);render();return}
 if(e.target.closest('[data-curr-next-question]')&&activeModule!==null){openModule(activeModule);return}
 if(e.target.closest('[data-curr-save-note]')&&activeModule!==null){const value=root.querySelector('[data-curr-note]')?.value||'';progress.notes??={};progress.notes[current+':'+activeModule]=value;save();root.querySelectorAll('.lesson-saved').forEach(x=>x.textContent='Apuntes guardados.');return}
 if(e.target.closest('[data-curr-save-response]')&&activeModule!==null){const value=root.querySelector('[data-curr-response]')?.value||'';progress.notes??={};progress.notes[current+':'+activeModule]=value;save();root.querySelectorAll('.lesson-saved').forEach(x=>x.textContent='Respuesta guardada.');return}
 if(e.target.closest('[data-curr-done]')&&activeModule!==null){done.add(current+':'+activeModule);save();activeModule=null;activeQuestion=null;activeAnswer=null;render();return}
});
